import useTooltip from "./core/useTooltip";

const Home = () => {
    const ytTooltip = useTooltip();
    const cvTooltip = useTooltip();
    return (
        <section className='home'>
            <div className='home_top'>
                <h1 className='text-h1'>XO</h1>
                <h1 className='text-h1'>Z</h1>
                <div>
                    <div style={{ position: "relative", display: "inline-block" }}
                    onMouseMove={ytTooltip.handleMouseMove}
                    onMouseEnter={ytTooltip.handleMouseMove}
                    onMouseLeave={ytTooltip.handleMouseLeave}>
                    <a href="https://www.youtube.com/@XobazJr" className="text-small" target="_blank" rel="noopener noreferrer">YouTube</a>
                    {ytTooltip.tooltip && (
                        <div ref={ytTooltip.tooltipRef} className="projects__tooltip"
                        style={{ backgroundColor: ytTooltip.tooltip.bg, color: ytTooltip.tooltip.color, position: "fixed", top: 0, left: 0, pointerEvents: "none", zIndex: 999 }}>
                        YouTube
                        </div>
                    )}
                    </div>

                    <div style={{ position: "relative", display: "inline-block" }}
                    onMouseMove={cvTooltip.handleMouseMove}
                    onMouseEnter={cvTooltip.handleMouseMove}
                    onMouseLeave={cvTooltip.handleMouseLeave}>
                    <a href="assets/documents/teerapat_kotanart_cv.pdf" className="text-small home_cv" download rel="noopener noreferrer">Request CV</a>
                    {cvTooltip.tooltip && (
                        <div ref={cvTooltip.tooltipRef} className="projects__tooltip"
                        style={{ backgroundColor: cvTooltip.tooltip.bg, color: cvTooltip.tooltip.color, position: "fixed", top: 0, left: 0, pointerEvents: "none", zIndex: 999 }}>
                        Request CV
                        </div>
                    )}
                    </div>
                </div>
                </div>
                <div className='home_center'>
                <p className='text-small'>XobazJr</p>
                <h3 className='text-h3'>Teerapat Kotanart</h3>
                <p className='text-small'>Full-Stack Devlopment</p>
                </div>
                <div className='home_bottom'>
                <h1 className='text-h1'>BA</h1>
                <h1 className='text-h1'>JR</h1>
            </div>
        </section>
    );
}

export default Home;
